// ── Configuration ─────────────────────────────────────────────
const IMAGE_NAME = env.get("NODE_RED_CONTAINER_NAME");
const TAG_DIR = env.get("NODE_RED_CONTAINER_DIRECTORY");
const TAG_FILE = `${TAG_DIR}/image:tag`;

if (!IMAGE_NAME || !TAG_DIR) {
    node.error("Missing required environment variables: NODE_RED_CONTAINER_NAME and/or NODE_RED_CONTAINER_DIRECTORY");
    return null;
}
// ──────────────────────────────────────────────────────────────

const now = new Date();
const curY = now.getFullYear();
const curM = now.getMonth() + 1;  // 1-12

let newTag;

if (!fs.existsSync(TAG_FILE)) {
    // File does not exist: create with YYYY.MM.1
    newTag = `${curY}.${curM}.1`;

} else {
    const content = fs.readFileSync(TAG_FILE, 'utf8').trim();
    // Expected format: imagename:YYYY.MM.patch
    const match = content.match(/:(\d+)\.(\d+)\.(\d+)$/);

    if (!match) {
        // Unreadable format: reset
        newTag = `${curY}.${curM}.1`;

    } else {
        let [, fileY, fileM, fileP] = match.map(Number);

        if (fileY === curY && fileM === curM) {
            // Same year and month: bump patch
            newTag = `${curY}.${curM}.${fileP + 1}`;

        } else {
            // Different month or year: compute next month
            let nextY = fileY;
            let nextM = fileM + 1;
            if (nextM > 12) {
                nextY += 1;
                nextM = 1;
            }
            newTag = `${nextY}.${nextM}.1`;
        }
    }
}

const fileContent = `${IMAGE_NAME}:${newTag}`;
fs.writeFileSync(TAG_FILE, fileContent, 'utf8');

msg.payload = fileContent;
node.status({ fill: "green", shape: "dot", text: fileContent });
return msg;

let min = "zzzzzzzz-zzzz-zzzz-zzzz-zzzzzzzzzzzz"
let arr = msg.payload;
let i;
let j=0;
let del=[];
let priority="secondary";

for (i = 0; i < arr.length - 1; i = i + 2) {
    if ( (arr[i] < min) && ( ( Date.now() - parseFloat(arr[i+1]) ) < 8000 ) ) min = arr[i] ;
    if ( (Date.now() - parseFloat(arr[i + 1])) >= 8000 ) {
        del[j] = arr[i];
        j=j+1;
    }
}

if ( flow.get("uuid") == min ) priority="primary"

msg.centre_id=flow.get("centreid");
msg.payload = priority;
msg.del = del;
msg.uuid = flow.get("uuid");

return msg;

let topic = msg.topic;
let topicArray = topic.split("/");

// Defaults
msg.topic = null;

// 1. Monitor topic
if (topicArray[0] === "monitor") {
    msg.check = topicArray[5] == null;
    return msg;
}

// 2. Experimental discipline topic
const DISCIPLINES = ["weather", "climate", "hydrology", "atmospheric-composition", "cryosphere", "ocean", "space-weather"];
if (DISCIPLINES.includes(topicArray[6]) && topicArray[7] === "experimental") {
    msg.check = true;
    return msg;
}

const topicShort = topicArray.splice(6, topicArray.length).join('/');
msg.payload = null;

// 3. Cache + recommended → reject
if (topicArray[0] === "cache" && topicArray[5] === "recommended") {
    msg.check = false;
    return msg;
}

// 4. GTS-to-WIS2
if (topicArray[3].endsWith("-gts-to-wis2")) {
    msg.check = true;
    return msg;
}

// 5. Metadata
if (topicArray[4] === "metadata") {
    msg.check = true;
    msg.topic = topicArray[5] != null ? "FT2025-2" : null;
    return msg;
}

// 6. Data core/recommended
if (topicArray[4] === "data" && ["core", "recommended"].includes(topicArray[5])) {
    msg.check = true;
    msg.topic = "topic_" + md5(topicShort);
    return msg;
}

// Default: reject
msg.check = false;
return msg;

