const isMonitor = msg.topic && msg.topic.startsWith("monitor");
const validatorKey = isMonitor ? "WME_Validator" : "WNM_Validator";
const validate = flow.get(validatorKey);

if (!validate) {
    node.error(`Schema validator ${validatorKey} not initialized`, msg);
    return null;
}
return validate(msg.payload) ? [msg, null] : [null, msg];

const schema = msg.schema;
try {
  const linksItems = schema.allOf[1].properties.data.properties.links.items;
  delete linksItems.$id;
  delete linksItems.$schema;
} catch (e) {}

const ajv = new Ajv({ allErrors: true, strict: false });
addFormats(ajv);
flow.set("WME_Validator", ajv.compile(schema));
return null;

const BATCH_SIZE = 100;
const BATCH_TIMEOUT = 5000;
const VECTOR_LOG = flow.get("vector"); // "docker", or an http(s) URL like https://vector:8686

if (!VECTOR_LOG) return;

// --- topic filter (regex compiled once, at /admin/set) ---
const topicMatchRegex = flow.get('topic_match_compiled');
if (topicMatchRegex && !topicMatchRegex.test(msg.topic)) {
    return; // topic doesn't match, drop silently
}
// --- end filter ---

const record = {
    received_at: Date.now(),
    received_from: flow.get('centreid'),
    topic: msg.topic,
    payload: msg.payload
};

let batch = context.get('batch') || [];
let timer = context.get('timer');

batch.push(record);
context.set('batch', batch);

const flush = () => {
    let current = context.get('batch') || [];
    if (current.length === 0) return;
    context.set('batch', []);
    context.set('timer', null);

    const body = current.map(r => JSON.stringify(r)).join('\n');

    if (VECTOR_LOG === 'docker') {
        // Write straight to Node-RED's stdout — captured by Docker's log driver
        console.log(body);
    } else if (/^https?:\/\//i.test(VECTOR_LOG)) {
        const url = new URL(VECTOR_LOG);
        const isHttps = url.protocol === 'https:';
        const client = isHttps ? https : http;

        const options = {
            hostname: url.hostname,
            port: url.port || (isHttps ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-ndjson',
                'Content-Length': Buffer.byteLength(body)
            },
            rejectUnauthorized: false
        };

        const req = client.request(options, (res) => {
            if (res.statusCode !== 200) {
                node.error(`Vector returned ${res.statusCode}`);
            }
        });
        req.on('error', (e) => node.error(`Vector error: ${e.message}`));
        req.write(body);
        req.end();
    } else {
        node.error(`Unrecognized VECTOR_LOG value: "${VECTOR_LOG}" (expected "docker" or an http(s) URL)`);
    }
};

if (batch.length >= BATCH_SIZE) {
    if (timer) clearTimeout(timer);
    flush();
} else if (!timer) {
    context.set('timer', setTimeout(flush, BATCH_TIMEOUT));
}

