return null;

const payload = msg.payload || {};

if (typeof payload.debug !== 'undefined') {
    flow.set('debug', !!payload.debug);
}

if (typeof payload.topic_match !== 'undefined') {
    const pattern = payload.topic_match;

    if (!pattern) {
        flow.set('topic_match', null);
        flow.set('topic_match_compiled', null);
    } else {
        try {
            const compiled = new RegExp(pattern);
            flow.set('topic_match', pattern);          // raw string, for display
            flow.set('topic_match_compiled', compiled); // compiled, for the hot path
        } catch (e) {
            node.error(`Invalid topic_match regexp: ${e.message}`);
            msg.statusCode = 400;
            msg.payload = { error: `Invalid topic_match regexp: ${e.message}` };
            return msg;
        }
    }
}

msg.payload = {
    debug: flow.get('debug') || false,
    topic_match: flow.get('topic_match') || null
};
return msg;

const ENV_NAMES = [
    "MQTT_PUB_BROKER",
    "MQTT_PUB_BROKER_2",
    "MQTT_PUB_BROKER_3",
    "MQTT_PUB_BROKER_4",
    "MQTT_PUB_BROKER_5"
];

const definedCount = ENV_NAMES.filter(name => {
    const val = env.get(name);
    return val !== undefined && val !== null && val !== "";
}).length;

var state = flow.get('brokerState') || {};
var id = msg.status.source.id;
state[id] = (msg.status.fill === 'green');
flow.set('brokerState', state);

var values = Object.values(state);

// true as soon as at least one tracked broker is connected
var anyConnected = values.some(function (v) { return v === true; });
flow.set('anyBrokersConnected', anyConnected);

// true only when every DEFINED broker is connected
var allConnected = definedCount > 0
    && values.length === definedCount
    && values.every(function (v) { return v === true; });
flow.set('allBrokersConnected', allConnected);

return { payload: allConnected };
